// === PIN VERIFICATION & SESSION AUTH ===
// A soft lock to keep work and earnings private on a shared screen. The unlock lasts until this
// page/tab is closed (a refresh keeps you signed in; there is no daily time-out).
let pinMode = 'enter';   // 'enter' | 'create' | 'change'
let pinUser = null;
let pinStoredHash = null;

const unlockedUsers = {};   // in-memory backup in case browser storage is blocked
function isUnlocked(userId) {
  if (unlockedUsers[userId]) return true;
  try { return sessionStorage.getItem('dcdUnlock_' + userId) === '1'; } catch (e) { return false; }
}

function setUnlocked(userId) {
  unlockedUsers[userId] = true;
  // sessionStorage survives a refresh but is cleared when the page/tab is closed - no daily time-out
  try { sessionStorage.setItem('dcdUnlock_' + userId, '1'); } catch (e) {}
}

async function hashPin(userId, pin) {
  const text = 'dcd-pin|' + userId + '|' + pin;
  if (window.crypto && crypto.subtle) {
    const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
    return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
  }
  let h1 = 5381, h2 = 52711;   // fallback for browsers without crypto.subtle
  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i);
    h1 = ((h1 * 33) ^ c) >>> 0;
    h2 = ((h2 * 33) ^ c) >>> 0;
  }
  return 'f' + h1.toString(16) + h2.toString(16);
}

async function startPinFlow(userId) {
  pinUser = userId;
  try {
    const snap = await db.ref('userPins/' + userId).once('value');
    const v = snap.val();
    pinStoredHash = v && v.hash ? v.hash : null;
  } catch (e) {
    alert('Could not reach the database to check your PIN. Check your connection and try again.');
    return;
  }
  showPinModal(pinStoredHash ? 'enter' : 'create');
}

function showPinModal(mode) {
  pinMode = mode;
  const name = USERS[pinUser] ? USERS[pinUser].name : '';
  const show = (id, on) => { document.getElementById(id).style.display = on ? 'block' : 'none'; };
  document.getElementById('pin-title').textContent = mode === 'enter' ? 'Enter your PIN' : (mode === 'create' ? 'Create a PIN' : 'Change PIN');
  document.getElementById('pin-sub').textContent = mode === 'enter'
    ? name + ' — enter your PIN to continue.'
    : (mode === 'create'
        ? name + ' — choose a 4–6 digit PIN. You will only be asked again after you close this page.'
        : 'Enter your current PIN, then choose a new one.');
  show('pin-current', mode === 'change');
  show('pin-confirm', mode !== 'enter');
  document.getElementById('pin-input').placeholder = mode === 'enter' ? 'PIN' : 'New PIN (4–6 digits)';
  ['pin-current', 'pin-input', 'pin-confirm'].forEach(id => { document.getElementById(id).value = ''; });
  document.getElementById('pin-error').style.display = 'none';
  document.getElementById('pin-submit').textContent = mode === 'enter' ? 'Unlock' : 'Save PIN';
  document.getElementById('pin-overlay').style.display = 'flex';
  setTimeout(() => document.getElementById(mode === 'change' ? 'pin-current' : 'pin-input').focus(), 100);
}

function closePinModal() {
  document.getElementById('pin-overlay').style.display = 'none';
}

async function openChangePin() {
  if (!currentUser) return;
  pinUser = currentUser;
  try {
    const snap = await db.ref('userPins/' + pinUser).once('value');
    const v = snap.val();
    pinStoredHash = v && v.hash ? v.hash : null;
  } catch (e) { alert('Could not reach the database. Try again.'); return; }
  showPinModal(pinStoredHash ? 'change' : 'create');
}

function finishUnlock() {
  const u = pinUser;
  setUnlocked(u);
  closePinModal();
  if (currentUser !== u) loginAs(u);   // already signed in = just changed/created a PIN
}

async function submitPin() {
  const err = msg => {
    const e = document.getElementById('pin-error');
    e.textContent = msg;
    e.style.display = 'block';
  };
  const valid = /^[0-9]{4,6}$/;
  const pin = document.getElementById('pin-input').value.trim();
  const confirmPin = document.getElementById('pin-confirm').value.trim();
  try {
    if (pinMode === 'enter') {
      if (!valid.test(pin)) return err('Enter your 4–6 digit PIN.');
      if (await hashPin(pinUser, pin) !== pinStoredHash) {
        document.getElementById('pin-input').value = '';
        return err('Incorrect PIN.');
      }
      finishUnlock();
      return;
    }
    if (pinMode === 'change') {
      const cur = document.getElementById('pin-current').value.trim();
      if (await hashPin(pinUser, cur) !== pinStoredHash) return err('Current PIN is incorrect.');
    }
    if (!valid.test(pin)) return err('PIN must be 4–6 digits.');
    if (pin !== confirmPin) return err('PINs do not match.');
    const newHash = await hashPin(pinUser, pin);
    await db.ref('userPins/' + pinUser).set({ hash: newHash, setAt: Date.now() });
    pinStoredHash = newHash;
    const wasChange = pinMode === 'change';
    finishUnlock();
    if (wasChange) alert('PIN changed.');
  } catch (e) {
    err('Something went wrong: ' + e.message);
  }
}

// === PERSONAL LINKS & USER LOGIN ===
function adminUserId() { return Object.keys(USERS).find(k => USERS[k].role === 'admin'); }

// Only someone who has unlocked the admin login in this browser session can switch between users
function canSwitchUsers() { const a = adminUserId(); return !!(a && isUnlocked(a)); }

function updateSwitchUI() {
  const can = canSwitchUsers();
  const sw = document.getElementById('active-user-switch');
  if (sw) sw.style.display = can ? '' : 'none';
  const badge = document.getElementById('active-user-badge');
  if (badge) badge.style.cursor = can ? 'pointer' : 'default';
}

// mode: 'dept' = everyone in the selected department, 'admin' = only the admin, 'one' = a single person, 'all' = everyone (admin switching), 'none' = nobody
let loginCardsMode = 'dept';
let loginCardsUserId = null;
let loginCardsMessage = null;

function showLoginCards(mode, userId, message) {
  loginCardsMode = mode;
  loginCardsUserId = userId;
  loginCardsMessage = message;
  const adminId = adminUserId();
  const selectedDept = document.getElementById('dept-select').value;
  const cards = document.querySelector('.user-cards');
  cards.replaceChildren();
  Object.entries(USERS).forEach(([id, user]) => {
    const show = user.dept === selectedDept &&
      (mode === 'dept' || mode === 'all' || (mode === 'admin' && id === adminId) || (mode === 'one' && id === userId));
    if (!show) return;

    const card = document.createElement('div');
    card.className = 'user-card';
    card.dataset.user = id;
    card.addEventListener('click', () => loginAs(id));

    const avatar = document.createElement('div');
    avatar.className = 'user-avatar';
    avatar.style.background = user.color;
    avatar.textContent = user.initials;

    const name = document.createElement('div');
    name.className = 'user-card-name';
    name.textContent = user.name;

    const subtitle = document.createElement('div');
    subtitle.className = 'user-card-sub';
    subtitle.textContent = 'Tap to sign in';

    card.append(avatar, name, subtitle);
    cards.appendChild(card);
  });
  const wrap = document.getElementById('dept-wrap');
  if (wrap) wrap.style.display = (mode === 'none' || (mode === 'one' && userId !== adminId)) ? 'none' : '';
  const note = document.getElementById('login-note');
  if (note) { note.textContent = message || ''; note.style.display = message ? 'block' : 'none'; }
}

function initLoginFromLink(search) {
  const u = new URLSearchParams(search !== undefined ? search : location.search).get('user');
  if (!u) { showLoginCards('dept'); return; }
  if (!USERS[u]) { showLoginCards('none', null, "This link isn't valid. Ask the admin for your personal link."); return; }
  document.getElementById('dept-select').value = USERS[u].dept;
  showLoginCards('one', u);
  loginAs(u);   // asks for the PIN, or goes straight in if this tab is already unlocked
}

function buildPersonalLinks(base) {
  return Object.keys(USERS).map(id => ({
    id, name: USERS[id].name, role: USERS[id].role,
    dept: DEPT_LABELS[USERS[id].dept] || USERS[id].dept,
    url: base + '?user=' + encodeURIComponent(id)
  }));
}

function openLinksModal() {
  if (!requireAdmin()) return;
  const base = location.href.split('#')[0].split('?')[0];
  document.getElementById('links-list').innerHTML = buildPersonalLinks(base).map(l =>
    '<div style="padding:0.7rem 0.75rem;border-bottom:1px solid var(--border);">'
    + '<div style="font-size:0.75rem;font-weight:700;">' + escAttr(l.name) + ' <span style="font-weight:400;color:var(--muted);">· ' + escAttr(l.dept) + (l.role === 'admin' ? ' · admin' : '') + '</span></div>'
    + '<div style="display:flex;gap:0.5rem;margin-top:0.35rem;">'
    + '<input type="text" readonly value="' + escAttr(l.url) + '" onclick="this.select()" style="flex:1;min-width:0;background:var(--surface2);border:1px solid var(--border);color:var(--text);font-family:IBM Plex Mono,monospace;font-size:0.68rem;padding:0.35rem 0.5rem;border-radius:3px;"/>'
    + '<button data-url="' + escAttr(l.url) + '" onclick="copyLink(this)" style="font-family:Syne,sans-serif;font-weight:700;font-size:0.65rem;text-transform:uppercase;padding:0.35rem 0.8rem;cursor:pointer;border-radius:3px;background:transparent;color:var(--accent2);border:1px solid var(--accent2);">Copy</button>'
    + '</div></div>').join('');
  document.getElementById('links-overlay').style.display = 'flex';
}
function closeLinksModal() { document.getElementById('links-overlay').style.display = 'none'; }

function copyLink(btn) {
  const url = btn.dataset.url;
  const done = () => showToast('Link copied');
  if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(url).then(done).catch(() => prompt('Copy this link:', url));
  else prompt('Copy this link:', url);
}

function loginAs(userId) {
  // PIN lock: only continue if this user has unlocked today in this browser session
  if (!isUnlocked(userId)) { startPinFlow(userId); return; }
  try {
    currentUser = userId;
    currentDept = (USERS[userId] && USERS[userId].dept) || 'DCD';
    applyRoleUI();
    const user = USERS[userId];
    if (!user) { alert('Unknown user: ' + userId); return; }

    // Set user-specific Firebase refs
    TICKS_REF = db.ref('users/' + userId + '/ticks/' + TODAY);
    BER_REF = db.ref('users/' + userId + '/ber/' + TODAY);
    HISTORY_REF = db.ref('users/' + userId + '/history');

    // Update header badge
    document.getElementById('active-user-badge').style.display = 'flex';
    document.getElementById('active-user-name').textContent = user.name;
    document.getElementById('header-user-dot').style.background = user.color;
    document.getElementById('admin-btn').style.display = 'inline-block';
    document.getElementById('pin-btn').style.display = 'inline-block';

    // Hide login screen
    document.getElementById('login-screen').style.display = 'none';

    // Start Firebase listeners for this user
    startFirebaseListeners();

    // Listen to ALL users' ticks for live priority list view
    ALL_TICKS_REF.on('value', snap => {
      allUserTicks = snap.val() || {};
      updatePriorityTotals();
      if (currentTab === 'main') renderTable();
    });

    // Load data
    loadAll();
  } catch(err) {
    alert('Login error: ' + err.message);
    console.error(err);
  }
}

function onDeptChange(sel) {
  const notice = document.getElementById('dept-notice');
  const names = { PC: 'PC', PCB: 'PCB', Printers: 'Printers & Peripherals' };
  if (sel.value === 'DCD') {
    notice.style.display = 'none';
  } else {
    notice.textContent = names[sel.value] + " isn't set up yet — ask your admin to add it, then switch back to DCD for now.";
    notice.style.display = 'block';
  }
  showLoginCards(loginCardsMode, loginCardsUserId, loginCardsMessage);
}

function switchUser() {
  if (!canSwitchUsers()) return;   // only the admin can switch between users
  document.getElementById('dept-select').value = 'DCD';
  document.getElementById('dept-notice').style.display = 'none';
  // Detach listeners
  if (TICKS_REF) TICKS_REF.off();
  if (BER_REF) BER_REF.off();
  if (HISTORY_REF) HISTORY_REF.off();
  ALL_TICKS_REF.off();
  ticks = {}; bers = {}; outputRows = [];
  currentUser = null;
  document.getElementById('login-screen').style.display = 'flex';
  document.getElementById('active-user-badge').style.display = 'none';
  document.getElementById('pin-btn').style.display = 'none';
  document.getElementById('stats-bar').style.display = 'none';
  document.getElementById('tab-bar').style.display = 'none';
  document.getElementById('actions-bar').style.display = 'none';
  document.getElementById('table-wrap').style.display = 'none';
  document.getElementById('zero-section').style.display = 'none';
  document.getElementById('completed-wrap').style.display = 'none';
  document.getElementById('history-wrap').style.display = 'none';
  showLoginCards('all');
}

// === ROLE PERMISSIONS, CHANGE REQUESTS & CHANGELOG ===
// Only the admin edits grades/departments directly. Everyone else sends requests the admin approves.
let requestMode = 'new';
let reqWatchHandler = null;
let reqFirstLoad = true;

function isAdmin() { return !!(currentUser && USERS[currentUser] && USERS[currentUser].role === 'admin'); }

function requireAdmin() {
  if (isAdmin()) return true;
  alert('Only the admin can change this. Use "Request change" and the admin will approve it.');
  return false;
}

function userName(id) { return (USERS[id] && USERS[id].name) || id || 'Someone'; }

function applyRoleUI() {
  document.body.classList.toggle('role-admin', isAdmin());
  document.body.classList.toggle('role-user', !isAdmin());
  updateSwitchUI();
  updateNewBtn();
  updateRequestsBtn();
}

function logChange(action, partId, details) {
  try { CHANGE_LOG_REF.push({ at: Date.now(), by: currentUser || '', action, partId: partId || '', details: details || '' }); } catch (e) {}
}

function pendingRequests() {
  return Object.entries(changeRequests)
    .filter(([id, r]) => r && r.status === 'pending')
    .sort((a, b) => (a[1].requestedAt || 0) - (b[1].requestedAt || 0));
}

function updateRequestsBtn() {
  const b = document.getElementById('requests-btn');
  if (!b) return;
  const n = pendingRequests().length;
  b.textContent = '📥 Requests' + (n ? ' (' + n + ')' : '');
  b.style.borderColor = n ? 'var(--accent)' : 'var(--border)';
  b.style.color = n ? 'var(--accent)' : 'var(--text)';
}

function requestSummary(r) {
  const parts = [];
  if (r.grade) parts.push('Grade ' + ((r.before && r.before.grade) || 'none') + ' → ' + r.grade);
  (r.addDepts || []).forEach(d => parts.push('Add to ' + DEPT_LABELS[d]));
  (r.removeDepts || []).forEach(d => parts.push('Remove from ' + DEPT_LABELS[d]));
  return parts.join(' · ');
}

function partState(partId) {
  const gm = window.gradeMap || {};
  const depts = REQ_DEPTS.filter(d => DEPT_PARTS[d].has(partId));
  const known = !!(gm[partId] || depts.length || (window.allPartIds && window.allPartIds.has(partId)));
  return { grade: gm[partId] || '', depts, known };
}

function openRequestModal(mode, partId) {
  requestMode = mode;
  const pid = document.getElementById('request-partid');
  pid.value = partId || '';
  pid.readOnly = mode === 'change';
  document.getElementById('request-title').textContent = mode === 'new' ? 'Request a new part' : 'Request a change';
  document.getElementById('request-help').textContent = mode === 'new'
    ? 'Send a part with its grade and departments to the admin. It is added once the admin approves it.'
    : 'Ask the admin to change this part. It changes once the admin approves it.';
  fillRequestForm();
  document.getElementById('request-note').value = '';
  document.getElementById('request-error').style.display = 'none';
  document.getElementById('request-overlay').style.display = 'flex';
  renderMyRequests();
  setTimeout(() => (mode === 'new' ? pid : document.getElementById('request-grade')).focus(), 100);
}

function closeRequestModal() { document.getElementById('request-overlay').style.display = 'none'; }
function requestChangeFor(btn) { openRequestModal('change', btn.dataset.pid); }
function requestPartChanged() { if (requestMode === 'new') fillRequestForm(); }

// Show the part's current grade/departments and pre-fill the form with them
function fillRequestForm() {
  const pid = document.getElementById('request-partid').value.trim().toUpperCase();
  const st = partState(pid);
  const info = document.getElementById('request-current');
  if (pid && st.known) info.textContent = 'Currently: grade ' + (st.grade || 'none') + ' · ' + (st.depts.length ? st.depts.map(d => DEPT_LABELS[d]).join(', ') : 'on no department list');
  else info.textContent = pid ? 'New part — not in the system yet.' : '';
  document.getElementById('request-grade').value = st.grade || '';
  REQ_DEPTS.forEach(d => { document.getElementById('request-dept-' + d).checked = st.known ? st.depts.includes(d) : d === currentDept; });
}

function submitRequest() {
  const err = m => { const e = document.getElementById('request-error'); e.textContent = m; e.style.display = 'block'; };
  const partId = document.getElementById('request-partid').value.trim().toUpperCase();
  if (!looksLikePartId(partId)) return err('Enter a valid part ID (for example ABC-DEF-123).');
  const st = partState(partId);
  const grade = document.getElementById('request-grade').value;
  const want = REQ_DEPTS.filter(d => document.getElementById('request-dept-' + d).checked);
  const gradeChange = grade && grade !== st.grade ? grade : '';
  const add = want.filter(d => !st.depts.includes(d));
  const remove = st.depts.filter(d => !want.includes(d));
  if (!st.known) {
    if (!grade) return err('Choose a grade for the new part.');
    if (!want.length) return err('Tick at least one department.');
  }
  if (!gradeChange && !add.length && !remove.length) return err('Nothing to request: that part already has this grade and these departments.');
  CHANGE_REQ_REF.push({
    kind: st.known ? 'change' : 'new', partId, grade: gradeChange, addDepts: add, removeDepts: remove,
    note: document.getElementById('request-note').value.trim(),
    requestedBy: currentUser, requestedAt: Date.now(), status: 'pending',
    before: { grade: st.grade, depts: st.depts }
  });
  closeRequestModal();
  showToast('Request sent — the admin will review it');
}

function renderMyRequests() {
  const mine = Object.entries(changeRequests).filter(([id, r]) => r && r.requestedBy === currentUser)
    .sort((a, b) => (b[1].requestedAt || 0) - (a[1].requestedAt || 0)).slice(0, 8);
  const el = document.getElementById('request-mine');
  if (!mine.length) { el.innerHTML = ''; return; }
  const color = { pending: 'var(--muted)', approved: 'var(--green)', rejected: 'var(--accent)' };
  el.innerHTML = '<div style="font-size:0.62rem;color:var(--muted);text-transform:uppercase;letter-spacing:0.06em;margin:1rem 0 0.4rem;">Your recent requests</div>'
    + mine.map(([id, r]) => '<div style="font-size:0.7rem;padding:0.35rem 0;border-bottom:1px solid var(--border);">'
      + '<span style="font-family:IBM Plex Mono,monospace;">' + escAttr(r.partId) + '</span> — ' + escAttr(requestSummary(r))
      + ' <strong style="color:' + (color[r.status] || 'var(--muted)') + ';">' + escAttr(r.status) + '</strong>'
      + (r.decisionNote ? ' <span style="color:var(--muted);">(' + escAttr(r.decisionNote) + ')</span>' : '') + '</div>').join('');
}

function openRequestsModal() {
  if (!requireAdmin()) return;
  document.getElementById('requests-overlay').style.display = 'flex';
  renderRequests();
  loadChangeLog();
}
function closeRequestsModal() { document.getElementById('requests-overlay').style.display = 'none'; }

function fmtTime(ts) { return ts ? new Date(ts).toLocaleString('en-GB', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) : ''; }

function renderRequests() {
  const pend = pendingRequests();
  const btn = 'font-family:Syne,sans-serif;font-weight:700;font-size:0.65rem;text-transform:uppercase;padding:0.35rem 0.9rem;cursor:pointer;border-radius:3px;';
  let h = pend.length ? '' : '<div style="padding:1rem;color:var(--muted);font-size:0.75rem;">No requests waiting.</div>';
  pend.forEach(([id, r]) => {
    h += '<div style="padding:0.75rem;border-bottom:1px solid var(--border);">'
      + '<div style="font-size:0.65rem;color:var(--muted);">' + escAttr(userName(r.requestedBy)) + ' · ' + escAttr(fmtTime(r.requestedAt)) + ' · ' + (r.kind === 'new' ? 'NEW PART' : 'CHANGE') + '</div>'
      + '<div style="font-family:IBM Plex Mono,monospace;font-size:0.8rem;margin:0.2rem 0;">' + escAttr(r.partId) + '</div>'
      + '<div style="font-size:0.72rem;">' + escAttr(requestSummary(r)) + '</div>'
      + (r.note ? '<div style="font-size:0.68rem;color:var(--muted);margin-top:0.2rem;">Note: ' + escAttr(r.note) + '</div>' : '')
      + '<div style="margin-top:0.5rem;display:flex;gap:0.5rem;">'
      + '<button data-id="' + escAttr(id) + '" onclick="approveRequest(this)" style="' + btn + 'background:var(--green);color:white;border:none;">Approve</button>'
      + '<button data-id="' + escAttr(id) + '" onclick="rejectRequest(this)" style="' + btn + 'background:transparent;color:var(--accent);border:1px solid var(--accent);">Reject</button></div></div>';
  });
  const decided = Object.entries(changeRequests).filter(([id, r]) => r && r.status !== 'pending')
    .sort((a, b) => (b[1].decidedAt || 0) - (a[1].decidedAt || 0)).slice(0, 6);
  if (decided.length) {
    h += '<div style="font-size:0.62rem;color:var(--muted);text-transform:uppercase;letter-spacing:0.06em;padding:0.75rem 0.75rem 0.25rem;">Recently decided</div>'
      + decided.map(([id, r]) => '<div style="font-size:0.7rem;padding:0.3rem 0.75rem;"><span style="font-family:IBM Plex Mono,monospace;">' + escAttr(r.partId)
        + '</span> — ' + escAttr(requestSummary(r)) + ' (' + escAttr(userName(r.requestedBy)) + ') <strong>' + escAttr(r.status) + '</strong></div>').join('');
  }
  document.getElementById('requests-list').innerHTML = h;
}

async function loadChangeLog() {
  const el = document.getElementById('changelog-list');
  try {
    const snap = await CHANGE_LOG_REF.limitToLast(40).once('value');
    const rows = Object.values(snap.val() || {}).sort((a, b) => (b.at || 0) - (a.at || 0));
    el.innerHTML = rows.length ? rows.map(r => '<div style="font-size:0.68rem;padding:0.3rem 0.75rem;border-bottom:1px solid var(--border);">'
      + '<span style="color:var(--muted);">' + escAttr(fmtTime(r.at)) + ' · ' + escAttr(userName(r.by)) + '</span> — ' + escAttr(r.action)
      + (r.partId ? ' <span style="font-family:IBM Plex Mono,monospace;">' + escAttr(r.partId) + '</span>' : '')
      + (r.details ? ' <span style="color:var(--muted);">' + escAttr(r.details) + '</span>' : '') + '</div>').join('')
      : '<div style="padding:0.75rem;color:var(--muted);font-size:0.72rem;">Nothing logged yet.</div>';
  } catch (e) { el.innerHTML = '<div style="padding:0.75rem;color:var(--muted);font-size:0.72rem;">Could not load the log.</div>'; }
}

function approveRequest(btn) {
  if (!requireAdmin()) return;
  const id = btn.dataset.id;
  const r = changeRequests[id];
  if (!r || r.status !== 'pending') return;
  if (r.grade) setPartGrade(r.partId, r.grade, true);
  (r.addDepts || []).forEach(d => setPartDept(r.partId, d, true, true));
  (r.removeDepts || []).forEach(d => setPartDept(r.partId, d, false, true));
  CHANGE_REQ_REF.child(id).update({ status: 'approved', decidedBy: currentUser, decidedAt: Date.now() });
  logChange('Approved request', r.partId, requestSummary(r) + ' (requested by ' + userName(r.requestedBy) + ')');
  setTimeout(loadChangeLog, 600);
}

function rejectRequest(btn) {
  if (!requireAdmin()) return;
  const id = btn.dataset.id;
  const r = changeRequests[id];
  if (!r || r.status !== 'pending') return;
  const reason = prompt('Reason for rejecting (optional, the requester will see it):');
  if (reason === null) return;
  CHANGE_REQ_REF.child(id).update({ status: 'rejected', decidedBy: currentUser, decidedAt: Date.now(), decisionNote: reason.trim() });
  logChange('Rejected request', r.partId, requestSummary(r) + ' (requested by ' + userName(r.requestedBy) + ')' + (reason.trim() ? ': ' + reason.trim() : ''));
  setTimeout(loadChangeLog, 600);
}

// === LIVE SYNC LISTENERS & MIGRATIONS ===
let lastSeenUpload = null;
let uploadWatchHandler = null;
let reloadTimer = null;

async function applyDcdMoveOnce() {
  try {
    const mRef = db.ref('migrations/dcdMoveToOwnDept1');
    if ((await mRef.once('value')).val()) return;
    Object.entries(DCD_MOVE_ONCE).forEach(([p, d]) => {
      const key = safeKey(p);
      DCD_PARTS.delete(p);
      DCD_PARTS_REF.child(key).remove();
      if (customParts[key]) { customParts[key].isDCD = false; CUSTOM_PARTS_REF.child(key).update({ isDCD: false }); }
      if (DEPT_PARTS[d] && !DEPT_PARTS[d].has(p)) { DEPT_PARTS[d].add(p); DEPT_PARTS_REF.child(d).child(key).set(p); }
    });
    await mRef.set(Date.now());
  } catch (e) { console.error('DCD move skipped', e); }
}

function onUploadChange(snap) {
  const t = snap.val() || 0;
  if (lastSeenUpload === null) { lastSeenUpload = t; return; }   // first value = the version already on screen
  if (!t || t === lastSeenUpload) return;
  lastSeenUpload = t;
  showToast('New report uploaded — updating your list…');
  scheduleReload();
}

// Coming back to the page after it sat in the background or the computer slept: check for a missed upload
document.addEventListener('visibilitychange', async () => {
  if (document.hidden || !currentUser || lastSeenUpload === null) return;
  try {
    const t = (await db.ref('lastUpdated').once('value')).val() || 0;
    if (t && t !== lastSeenUpload) onUploadChange({ val: () => t });
  } catch (e) {}
});

function scheduleReload() {
  clearTimeout(reloadTimer);
  reloadTimer = setTimeout(() => loadAll(true), 700);
}

function startFirebaseListeners() {
  if (reqWatchHandler) CHANGE_REQ_REF.off('value', reqWatchHandler);
  reqFirstLoad = true;
  reqWatchHandler = snap => {
    const next = snap.val() || {};
    const prev = changeRequests;
    changeRequests = next;
    if (!reqFirstLoad) {
      const pendingBefore = Object.values(prev).filter(r => r && r.status === 'pending').length;
      if (isAdmin() && pendingRequests().length > pendingBefore) showToast('New change request waiting for your approval');
      Object.entries(next).forEach(([id, r]) => {
        const p = prev[id];
        if (p && p.status === 'pending' && r.status !== 'pending' && r.requestedBy === currentUser) showToast('Your request for ' + r.partId + ' was ' + r.status);
      });
    }
    reqFirstLoad = false;
    updateRequestsBtn();
    const ro = document.getElementById('requests-overlay');
    if (ro && ro.style.display === 'flex') renderRequests();
    const qo = document.getElementById('request-overlay');
    if (qo && qo.style.display === 'flex') renderMyRequests();
  };
  CHANGE_REQ_REF.on('value', reqWatchHandler);

  if (uploadWatchHandler) db.ref('lastUpdated').off('value', uploadWatchHandler);
  lastSeenUpload = null;
  uploadWatchHandler = onUploadChange;
  db.ref('lastUpdated').on('value', uploadWatchHandler);

  STOCK_ADJ_REF.on('value', snap => {
    stockAdjustments = snap.val() || {};
    updatePriorityTotals();
    if (currentTab === 'main') renderTable();
  });

  NO_DEPT_REF.on('value', snap => {
    if (!dataLoaded) return;
    const next = new Set(Object.values(snap.val() || {}));
    if (next.size === noDeptParts.size && [...next].every(p => noDeptParts.has(p))) return;
    noDeptParts = next;
    scheduleReload();
  });

  GRADES_REF.on('value', snap => {
    const v = snap.val();
    if (!v || !dataLoaded) return;
    const next = {};
    Object.values(v).forEach(e => { if (e && e.partId && e.grade) next[e.partId] = e.grade; });
    const ks = Object.keys(next);
    if (ks.length === Object.keys(partGrades).length && ks.every(p => partGrades[p] === next[p])) return;
    partGrades = next;
    scheduleReload();
  });

  DEPT_PARTS_REF.on('value', snap => {
    const v = snap.val();
    if (!v || !dataLoaded) return;
    let changed = false;
    ['PC', 'PCB', 'Printers'].forEach(d => {
      const next = new Set(Object.values(v[d] || {}));
      const cur = DEPT_PARTS[d];
      if (next.size === cur.size && [...next].every(p => cur.has(p))) return;
      cur.clear();
      next.forEach(p => cur.add(p));
      changed = true;
    });
    if (changed) scheduleReload();
  });

  DCD_PARTS_REF.on('value', snap => {
    const v = snap.val();
    if (!v || !dataLoaded) return;
    const next = new Set(Object.values(v));
    const same = next.size === DCD_PARTS.size && [...next].every(p => DCD_PARTS.has(p));
    if (same) return;
    DCD_PARTS.clear();
    next.forEach(p => DCD_PARTS.add(p));
    scheduleReload();
  });

  CUSTOM_PARTS_REF.on('value', snap => {
    customParts = snap.val() || {};
    // Re-merge into gradeMap and DCD_PARTS live
    Object.values(customParts).forEach(cp => {
      if (!cp.partId) return;
      window.gradeMap = window.gradeMap || {};
      if (cp.grade) window.gradeMap[cp.partId] = cp.grade;
      if (cp.isDCD) DCD_PARTS.add(cp.partId);
    });
  });

  TICKS_REF.on('value', snap => {
    ticks = snap.val() || {};
    // Also write to allTicks so others can see
    if (currentUser) {
      ALL_TICKS_REF.child(currentUser).set(ticks);
    }
    updateDoneCount();
    if (currentTab === 'main') renderTable();
    else if (currentTab === 'done') renderCompleted();
    else if (currentTab === 'history') renderHistory();
    if (dataLoaded) saveToHistory();
  });

  BER_REF.on('value', snap => {
    bers = snap.val() || {};
    updateDoneCount();
    if (currentTab === 'main') renderTable();
    else if (currentTab === 'done') renderCompleted();
    else if (currentTab === 'history') renderHistory();
    if (dataLoaded) saveToHistory();
  });

  HISTORY_REF.on('value', snap => {
    historyData = snap.val() || {};
    // Rebuild manualPartsMap from today's history so manually-added parts survive refreshes
    if (historyData[TODAY]) {
      Object.entries(historyData[TODAY]).forEach(([key, entry]) => {
        if (!entry || !entry.partId) return;
        const cleanKey = key.replace(/^ber_/, '');
        manualPartsMap[cleanKey] = { partId: entry.partId, cls: entry.cls || '', val: entry.val || 0 };
      });
    }
    updateHistoryCount();
    if (currentTab === 'history') renderHistory();
  });
}

// === DATA FETCHERS (FIREBASE & GITHUB FALLBACK) ===
async function fetchFile(filename) {
  // Map filename to Firebase DB key
  const keyMap = {
    'Both PowerBi Complete.xlsx': 'powerbi',
    'New Repair Centre Back Order Report v1.csv': 'backorder'
  };
  const dbKey = keyMap[filename];

  // Try Firebase Database first (uploaded via admin panel)
  if (dbKey) {
    try {
      const snap = await db.ref('files/' + dbKey).once('value');
      const entry = snap.val();
      if (entry && entry.data) {
        const binary = atob(entry.data);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
        return bytes.buffer;
      }
    } catch(e) { /* fall through to GitHub */ }
  }

  // Fall back to GitHub
  const bust = Date.now();
  const urls = [
    `https://raw.githubusercontent.com/NotKamran07/dcd-priority-list/main/${encodeURIComponent(filename)}?t=${bust}`,
    `https://cdn.jsdelivr.net/gh/NotKamran07/dcd-priority-list@main/${encodeURIComponent(filename)}?t=${bust}`
  ];
  for (const url of urls) {
    try {
      const res = await fetch(url, { cache: 'no-store' });
      if (res.ok) return await res.arrayBuffer();
    } catch(e) { continue; }
  }
  throw new Error(`Could not load "${filename}" — file not found in Firebase or GitHub. Please upload via the Admin panel.`);
}

async function loadXLSX(filename) {
  const buf = await fetchFile(filename);
  const wb = XLSX.read(buf, { type: 'array' });
  return XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { defval: '' });
}

async function loadCSV(filename) {
  const buf = await fetchFile(filename);
  const text = new TextDecoder('utf-8').decode(buf);
  const sections = text.trim().split(/\n\n+/);
  const allRows = [];
  sections.forEach(sec => {
    const wb = XLSX.read(sec, { type: 'string' });
    const rows = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { defval: '' });
    rows.forEach(r => {
      const norm = {};
      Object.keys(r).forEach(k => {
        if (/^part_id/i.test(k)) norm['Part ID'] = String(r[k]).trim();
        if (/^qty/i.test(k)) norm['Qty'] = Number(r[k]) || 0;
        if (/^user_def251/i.test(k)) norm['Note'] = String(r[k]).trim();
        if (/^user_def3$/i.test(k)) norm['Status'] = String(r[k]).trim();
      });
      norm['AllText'] = Object.keys(r).map(k => String(r[k])).join(' | ').toLowerCase();   // every column, for wording checks
      if (norm['Part ID']) allRows.push(norm);
    });
  });
  return allRows;
}

// === PART, GRADE, DEPARTMENT & BACKUP MUTATIONS ===
function setDCD(partId, on) {
  const key = safeKey(partId);
  if (on) { DCD_PARTS.add(partId); DCD_PARTS_REF.child(key).set(partId); }
  else { DCD_PARTS.delete(partId); DCD_PARTS_REF.child(key).remove(); }
  if (customParts[key]) {
    customParts[key].isDCD = on;
    CUSTOM_PARTS_REF.child(key).update({ isDCD: on });
  }
  scheduleReload();
}

// Give ungraded history entries for this part the new grade (this user's history)
function applyGradeToHistory(partId, grade) {
  if (!HISTORY_REF || !grade) return;
  const known = ['X', 'S', 'C', 'B', 'A', 'M'];
  const val = typeof GRADE_VALUE[grade] === 'number' ? GRADE_VALUE[grade] : 0;
  Object.keys(historyData || {}).forEach(date => {
    const day = historyData[date];
    if (!day || date === '_meta') return;
    Object.keys(day).forEach(key => {
      const e = day[key];
      if (!e || e.partId !== partId) return;
      if (known.includes((e.cls || '').toUpperCase())) return; // already graded
      const earned = (val * (e.count || 0)) + (e.berCount || 0) * 0.10;
      HISTORY_REF.child(date).child(key).update({ cls: grade, val, earned });
    });
  });
}

function setPartGrade(partId, grade, quiet) {
  if (!requireAdmin()) return;
  const key = safeKey(partId);
  window.gradeMap = window.gradeMap || {};
  const before = window.gradeMap[partId] || '';
  if (grade) {
    window.gradeMap[partId] = grade; partGrades[partId] = grade;
    GRADES_REF.child(key).set({ partId, grade });
  } else {
    delete window.gradeMap[partId]; delete partGrades[partId];
    GRADES_REF.child(key).remove();
  }
  if (customParts[key]) {   // keep any custom entry in step so it can't disagree
    customParts[key].grade = grade || '';
    CUSTOM_PARTS_REF.child(key).update({ grade: grade || '' });
  }
  applyGradeToHistory(partId, grade);
  if (!quiet) logChange('Grade changed', partId, (before || 'none') + ' → ' + (grade || 'none'));
  scheduleReload();
}

function gradeFromUngraded(sel) {
  if (!requireAdmin()) return;
  if (!sel.value) return;
  setPartGrade(sel.dataset.pid, sel.value);
}

// Add/remove a part on a department's list (DCD uses the DCD list)
// "None": no department will see this part on its priority list. Takes it off every department list
// and remembers the decision so it is not flagged or auto-assigned again.
function setPartNoDept(partId, on, quiet) {
  if (!requireAdmin()) return;
  const key = safeKey(partId);
  if (on) {
    Object.keys(DEPT_PARTS).forEach(d => { if (DEPT_PARTS[d].has(partId)) setPartDept(partId, d, false, true); });
    noDeptParts.add(partId);
    NO_DEPT_REF.child(key).set(partId);
    if (autoAssigned[key]) { delete autoAssigned[key]; db.ref('autoAssigned/' + key).remove(); }
    if (!quiet) logChange('Set to no department', partId, 'no department will show it');
  } else {
    noDeptParts.delete(partId);
    NO_DEPT_REF.child(key).remove();
    if (!quiet) logChange('No-department flag cleared', partId, '');
  }
  scheduleReload();
}

function setPartDept(partId, dept, on, quiet) {
  if (!requireAdmin()) return;
  if (!DEPT_PARTS[dept]) return;
  if (on && noDeptParts.has(partId)) { noDeptParts.delete(partId); NO_DEPT_REF.child(safeKey(partId)).remove(); }   // choosing a department replaces None
  if (!quiet) logChange(on ? 'Added to department' : 'Removed from department', partId, DEPT_LABELS[dept]);
  if (dept === 'DCD') { setDCD(partId, on); return; }
  const set = DEPT_PARTS[dept];
  const key = safeKey(partId);
  if (on) { set.add(partId); DEPT_PARTS_REF.child(dept).child(key).set(partId); }
  else { set.delete(partId); DEPT_PARTS_REF.child(dept).child(key).remove(); }
  if (dept === currentDept) scheduleReload();
}

function buildExportRows() {
  const gm = window.gradeMap || {};
  const ids = new Set([...(window.allPartIds || []), ...Object.keys(gm)]);
  Object.values(DEPT_PARTS).forEach(set => set.forEach(p => ids.add(p)));
  const yn = (set, id) => set.has(id) ? 'Yes' : 'No';
  return [...ids].sort().map(id => ({
    'Part ID': id,
    'Grade': gm[id] || '',
    'DCD': yn(DEPT_PARTS.DCD, id),
    'PC': yn(DEPT_PARTS.PC, id),
    'PCB': yn(DEPT_PARTS.PCB, id),
    'Printers & Peripherals': yn(DEPT_PARTS.Printers, id),
    'No department': noDeptParts.has(id) ? 'Yes' : 'No',
    'PowerBI team': (window.partTeams || {})[id] || ''
  }));
}

// Download every part with its grade and departments as a spreadsheet you can edit and import back
function exportPartsSheet() {
  if (!requireAdmin()) return;
  try {
    const ws = XLSX.utils.json_to_sheet(buildExportRows());
    ws['!cols'] = [{ wch: 34 }, { wch: 7 }, { wch: 6 }, { wch: 6 }, { wch: 6 }, { wch: 22 }, { wch: 26 }];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Parts');
    const out = XLSX.write(wb, { type: 'array', bookType: 'xlsx' });
    const blob = new Blob([out], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'parts-grades-departments-' + TODAY + '.xlsx';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(a.href), 5000);
  } catch (err) {
    alert('Export failed: ' + err.message);
  }
}

// Import a sheet: "Part ID" plus any of: a grade column (Grade / Part Class), a Department column,
// "Keep on DCD list" (No = remove), or a Yes/No column per department (as produced by Export)
async function importPartsSheet(input) {
  const file = input.files[0];
  input.value = '';
  if (!file) return;
  if (!requireAdmin()) return;
  try {
    const wb = XLSX.read(await file.arrayBuffer(), { type: 'array' });
    let rows = null;
    for (const n of wb.SheetNames) {
      const r = XLSX.utils.sheet_to_json(wb.Sheets[n], { defval: '' });
      if (r.length && Object.keys(r[0]).some(k => k.trim().toLowerCase() === 'part id')) { rows = r; break; }
    }
    if (!rows) { alert('Could not find a "Part ID" column in that file.'); return; }
    const deptByName = { 'dcd': 'DCD', 'rc dcd': 'DCD', 'pc': 'PC', 'rc pc': 'PC', 'pcb': 'PCB', 'rc pcb': 'PCB',
      'printers & peripherals': 'Printers', 'rc printers & peripherals': 'Printers', 'printers': 'Printers' };
    const deptCols = { 'dcd': 'DCD', 'pc': 'PC', 'pcb': 'PCB', 'printers & peripherals': 'Printers', 'p&p': 'Printers' };
    const gradeChanges = [], deptAdds = [], deptRemovals = [], noneOn = [], noneOff = [];
    const seen = new Set();
    const queue = (list, tag, id, d) => { const k = tag + id + '|' + d; if (seen.has(k)) return; seen.add(k); list.push([id, d]); };
    rows.forEach(r => {
      const keys = Object.keys(r);
      const col = names => keys.find(k => names.includes(k.trim().toLowerCase()));
      const val = k => (k ? String(r[k]).trim() : '');
      const id = val(col(['part id']));
      if (!id) return;
      const g = val(col(['grade', 'part class'])).toUpperCase();
      if (['X', 'S', 'C', 'B', 'A', 'M'].includes(g) && (window.gradeMap || {})[id] !== g) gradeChanges.push([id, g]);
      const d = val(col(['your department (fill in)'])) || val(col(['final department'])) || val(col(['department'])) || val(col(['suggested department']));
      const dk = deptByName[d.toLowerCase()];
      if (dk && !DEPT_PARTS[dk].has(id)) queue(deptAdds, 'a', id, dk);
      const keep = val(col(['keep on dcd list'])).toLowerCase();   // 'No' takes the part off the DCD list
      if ((keep === 'no' || keep === 'remove') && DEPT_PARTS.DCD.has(id)) queue(deptRemovals, 'r', id, 'DCD');
      Object.keys(deptCols).forEach(name => {                     // one Yes/No column per department
        const v = val(col([name])).toLowerCase();
        const key = deptCols[name];
        if (v === 'yes' && !DEPT_PARTS[key].has(id)) queue(deptAdds, 'a', id, key);
        if (v === 'no' && DEPT_PARTS[key].has(id)) queue(deptRemovals, 'r', id, key);
      });
      const none = val(col(['no department', 'none'])).toLowerCase();      // 'Yes' = no department shows it
      if (none === 'yes' && !noDeptParts.has(id)) noneOn.push(id);
      if (none === 'no' && noDeptParts.has(id)) noneOff.push(id);
    });
    if (!gradeChanges.length && !deptAdds.length && !deptRemovals.length && !noneOn.length && !noneOff.length) { alert('Nothing to change — everything in that sheet is already set.'); return; }
    if (!confirm('Apply ' + gradeChanges.length + ' grade change(s), add ' + deptAdds.length + ' part(s) to department lists and remove ' + deptRemovals.length + ' part(s) from department lists' + (noneOn.length || noneOff.length ? ', set ' + noneOn.length + ' to None and clear None on ' + noneOff.length : '') + '?')) return;
    gradeChanges.forEach(([id, g]) => {
      window.gradeMap[id] = g; partGrades[id] = g;
      GRADES_REF.child(safeKey(id)).set({ partId: id, grade: g });
      applyGradeToHistory(id, g);
    });
    deptAdds.forEach(([id, d]) => setPartDept(id, d, true, true));
    deptRemovals.forEach(([id, d]) => setPartDept(id, d, false, true));
    noneOff.forEach(id => setPartNoDept(id, false, true));
    noneOn.forEach(id => setPartNoDept(id, true, true));   // last, so None wins over any department in the same row
    logChange('Imported sheet', '', gradeChanges.length + ' grade change(s), ' + deptAdds.length + ' added to lists, ' + deptRemovals.length + ' removed (' + file.name + ')');
    scheduleReload();
    renderManageList();
    alert('Import complete: ' + gradeChanges.length + ' grade change(s), ' + deptAdds.length + ' added to department lists, ' + deptRemovals.length + ' removed from department lists, ' + noneOn.length + ' set to None, None cleared on ' + noneOff.length + '.');
  } catch (err) {
    alert('Import failed: ' + err.message);
  }
}

function manageDeleteCustom(btn) {
  if (!requireAdmin()) return;
  const pid = btn.dataset.pid;
  const builtIn = DCD_DEFAULT_SET.has(pid);
  if (!confirm('Delete the custom entry for ' + pid + '? Its grade override is removed' + (builtIn ? '.' : ' and it is taken off the DCD list.'))) return;
  const key = safeKey(pid);
  CUSTOM_PARTS_REF.child(key).remove();
  delete customParts[key];
  if (!builtIn) { DCD_PARTS.delete(pid); DCD_PARTS_REF.child(key).remove(); }
  scheduleReload();
  renderManageList();
}

function saveNewPart() {
  if (!requireAdmin()) return;
  const errEl = document.getElementById('newpart-error');
  errEl.style.display = 'none';
  const partId = document.getElementById('newpart-id-input').value.trim().toUpperCase();
  const grade = document.getElementById('newpart-grade-input').value;
  const isDCD = document.getElementById('newpart-dcd-input').checked;

  if (!partId) {
    errEl.textContent = 'Please enter a Part ID.';
    errEl.style.display = 'block';
    return;
  }
  const existingGrade = (window.gradeMap || {})[partId] || '';
  if (existingGrade && !(isDCD && !DCD_PARTS.has(partId))) {
    errEl.textContent = 'This part already has a grade assigned (' + existingGrade + ').';
    errEl.style.display = 'block';
    return;
  }

  const key = safeKey(partId);
  CUSTOM_PARTS_REF.child(key).set({ partId, grade: grade || existingGrade, isDCD, addedAt: Date.now() });
  if (grade) { partGrades[partId] = grade; GRADES_REF.child(key).set({ partId, grade }); }
  logChange('New part added', partId, (grade ? 'grade ' + grade : 'no grade') + (isDCD ? ', on DCD list' : ''));

  // Apply immediately in this session too
  window.gradeMap = window.gradeMap || {};
  if (grade) window.gradeMap[partId] = grade;
  if (isDCD) DCD_PARTS.add(partId);

  closeNewPartModal();
  if (isDCD) loadAll(); // refresh priority list so it can appear if on current report
}

async function downloadBackup() {
  try {
    const snap = await db.ref().once('value');
    const data = snap.val() || {};
    const reportFiles = data.files ? Object.keys(data.files) : [];
    delete data.files; // daily PowerBI/backorder/grading uploads are large and can simply be re-uploaded
    delete data.userPins; // keep PIN hashes out of backup files
    data._backupInfo = { createdAt: new Date().toISOString(), excluded: (reportFiles.length ? 'files (' + reportFiles.join(', ') + '), ' : '') + 'userPins' };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const d = new Date();
    const pad = n => String(n).padStart(2, '0');
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'dcd-backup-' + d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) + '-' + pad(d.getHours()) + pad(d.getMinutes()) + '.json';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(a.href), 5000);
  } catch (err) {
    alert('Backup failed: ' + err.message);
  }
}

// === ADMIN FILE UPLOAD & DOWNLOAD HANDLERS ===
function openAdmin() {
  adminLoggedIn = true;
  sessionStorage.setItem('adminLoggedIn', 'true');
  document.getElementById('admin-overlay').classList.add('open');
  document.getElementById('admin-login').style.display = 'none';
  document.getElementById('admin-panel').style.display = 'block';
}

function closeAdmin() {
  document.getElementById('admin-overlay').classList.remove('open');
  adminFiles = { powerbi: null, backorder: null };
  ['powerbi', 'backorder'].forEach(k => {
    const zone = document.getElementById('zone-' + k);
    const status = document.getElementById('status-' + k + '-admin');
    if (zone) zone.classList.remove('loaded');
    if (status) { status.textContent = 'Click to select file'; status.className = 'admin-upload-status'; }
  });
  document.getElementById('admin-upload-btn').disabled = true;
  document.getElementById('admin-progress').style.display = 'none';
  document.getElementById('admin-progress-fill').style.width = '0%';
  document.getElementById('admin-upload-msg').textContent = '';
}

function checkAdminPwd() {
  if (document.getElementById('admin-pwd').value === ADMIN_PWD) {
    adminLoggedIn = true;
    document.getElementById('admin-login').style.display = 'none';
    document.getElementById('admin-panel').style.display = 'block';
  } else {
    document.getElementById('admin-pwd-error').style.display = 'block';
    document.getElementById('admin-pwd').value = '';
    document.getElementById('admin-pwd').focus();
  }
}

async function downloadCurrentFile(key) {
  const btn = document.getElementById('dl-' + key);
  const prevText = btn.textContent;
  btn.textContent = 'Downloading…'; btn.disabled = true;
  try {
    const snap = await db.ref('files/' + key).once('value');
    const entry = snap.val();
    if (!entry || !entry.data) { alert('No ' + key + ' file has been uploaded yet.'); return; }
    const binary = atob(entry.data);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    const name = entry.name || (key + '.csv');
    const ext = (name.split('.').pop() || '').toLowerCase();
    const mimeMap = { xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', xls: 'application/vnd.ms-excel', csv: 'text/csv' };
    const blob = new Blob([bytes], { type: mimeMap[ext] || 'application/octet-stream' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = name;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(a.href), 5000);
  } catch (e) {
    alert('Download failed: ' + e.message);
  } finally {
    btn.textContent = prevText; btn.disabled = false;
  }
}

function handleAdminFile(key, input) {
  const file = input.files[0];
  if (!file) return;
  adminFiles[key] = file;
  document.getElementById('status-' + key + '-admin').textContent = '✓ ' + file.name;
  document.getElementById('status-' + key + '-admin').className = 'admin-upload-status ok';
  document.getElementById('zone-' + key).classList.add('loaded');
  document.getElementById('admin-upload-btn').disabled = !(adminFiles.powerbi || adminFiles.backorder);
}

function fileToBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = e => resolve(e.target.result.split(',')[1]);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

async function uploadAdminFiles() {
  const btn = document.getElementById('admin-upload-btn');
  const msg = document.getElementById('admin-upload-msg');
  const progress = document.getElementById('admin-progress');
  const fill = document.getElementById('admin-progress-fill');
  btn.disabled = true;
  progress.style.display = 'block';
  msg.style.color = 'var(--muted)';
  const toUpload = ['powerbi', 'backorder'].filter(k => adminFiles[k]);
  try {
    for (let i = 0; i < toUpload.length; i++) {
      const key = toUpload[i];
      msg.textContent = 'Uploading ' + adminFiles[key].name + '...';
      fill.style.width = ((i / toUpload.length) * 90) + '%';
      const b64 = await fileToBase64(adminFiles[key]);
      await db.ref('files/' + key).set({ data: b64, name: adminFiles[key].name, updatedAt: Date.now() });
    }
    fill.style.width = '100%';
    msg.textContent = '✓ Uploaded! All users will see the updated list.';
    msg.style.color = 'var(--green)';
    const uploadTs = Date.now();
    if (toUpload.includes('powerbi') || toUpload.includes('backorder')) {
      db.ref('filesUploadedAt').set(uploadTs);   // earlier work no longer affects the new numbers
      filesUploadedAt = uploadTs;
      db.ref('stockAdjustments').remove();       // fresh report = fresh stock
    }
    lastSeenUpload = uploadTs;                   // this page reloads itself below, so skip the automatic refresh
    db.ref('lastUpdated').set(uploadTs);         // written last so other pages find everything ready
    btn.disabled = false;
    setTimeout(() => { try { closeAdmin(); } catch (e) { console.error(e); } loadAll(); }, 2000);   // reload even if closing the panel fails
  } catch(err) {
    msg.textContent = '⚠ Upload failed: ' + err.message;
    msg.style.color = 'var(--accent)';
    btn.disabled = false;
    fill.style.width = '0%';
  }
}

document.addEventListener('click', e => { if (e.target.id === 'admin-overlay') closeAdmin(); });
